#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Apple Push Notifications setup for iOS push (GitHub #171).
# Produces the Supabase secrets the send-push Edge Function reads:
#   APNS_KEY_P8  APNS_KEY_ID  APNS_TEAM_ID  APNS_BUNDLE_ID  PUSH_FUNCTION_SECRET
# then deploys the function and hands the database its URL and secret (Vault),
# which is what switches the 15-second drain on.
# Nothing is written to .env: the key is a credential and only the hosted
# project needs it. Re-runnable; Apple lets you download a .p8 only once.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

BUNDLE_ID="com.ballparty.app"
DEFAULT_TEAM_ID="NS8CC9Z25V"

banner "Ball Party — Apple Push Notifications (APNs) setup"

stage "Enable Push Notifications on the app ID"
say "The app ID $BUNDLE_ID must have the Push Notifications capability."
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "Open the identifier $BUNDLE_ID."
step "Tick 'Push Notifications' under Capabilities."
step "Click Save (and Confirm if Apple asks about regenerating profiles)."
note "Already ticked? Then there is nothing to do here."
pause "Done? Press Enter."

stage "Create the APNs auth key (.p8)"
say "One key works for every app on the team, sandbox and production."
note "Apple allows two APNs keys per team. If both are used, reuse one you already have a .p8 for."
open_url "https://developer.apple.com/account/resources/authkeys/add"
step "Key Name: Ball Party APNs."
step "Tick 'Apple Push Notifications service (APNs)', then Continue and Register."
step "Click Download. Apple lets you download the .p8 ONCE; keep it somewhere safe."
step "Copy the Key ID shown on the key's page (10 characters)."
ask APNS_KEY_ID "Paste the Key ID:"
[[ -n "$APNS_KEY_ID" ]] || { warn "a Key ID is required"; exit 1; }

stage "Locate the key file and Team ID"
open_url "https://developer.apple.com/account#MembershipDetailsCard"
step "Team ID is under Membership details (10 characters)."
ask APNS_TEAM_ID "Team ID [$DEFAULT_TEAM_ID is what the Xcode project uses]:"
APNS_TEAM_ID="${APNS_TEAM_ID:-$DEFAULT_TEAM_ID}"
say "Now the downloaded file (AuthKey_${APNS_KEY_ID}.p8)."
ask APNS_P8_PATH "Path to the .p8 (drag the file into this window):"
APNS_P8_PATH="${APNS_P8_PATH//\\ / }"; APNS_P8_PATH="${APNS_P8_PATH%\"}"; APNS_P8_PATH="${APNS_P8_PATH#\"}"
APNS_P8_PATH="${APNS_P8_PATH/#\~/$HOME}"
[[ -f "$APNS_P8_PATH" ]] || { warn "no file at $APNS_P8_PATH"; exit 1; }
grep -q "BEGIN PRIVATE KEY" "$APNS_P8_PATH" || { warn "that does not look like an APNs .p8 key"; exit 1; }

stage "Store them as Supabase secrets"
say "Setting APNS_KEY_P8, APNS_KEY_ID, APNS_TEAM_ID and APNS_BUNDLE_ID on the linked project."
command -v supabase >/dev/null 2>&1 || { warn "install the Supabase CLI first"; exit 1; }
step "Make sure the CLI is linked to the hosted project (supabase link), then continue."
note "Running this against the wrong project would put the key there. Check the ref."
if confirm "Set the four secrets on the linked project now?"; then
  supabase secrets set \
    "APNS_KEY_P8=$(cat "$APNS_P8_PATH")" \
    "APNS_KEY_ID=$APNS_KEY_ID" \
    "APNS_TEAM_ID=$APNS_TEAM_ID" \
    "APNS_BUNDLE_ID=$BUNDLE_ID"
  say "Done. Keep the .p8 in your password manager, not in the repo."
else
  SKIPPED+=("supabase secrets set APNS_KEY_P8=... APNS_KEY_ID=$APNS_KEY_ID APNS_TEAM_ID=$APNS_TEAM_ID APNS_BUNDLE_ID=$BUNDLE_ID")
fi
stage "Deploy the sender and wake it from the database"
say "Deploys send-push, then lets the database call it (docs/ios/push.md)."
command -v openssl >/dev/null 2>&1 || { warn "openssl is needed to make the shared secret"; exit 1; }
step "Your Supabase project ref is in the dashboard URL: supabase.com/dashboard/project/<ref>."
ask SUPABASE_PROJECT_REF "Project ref:"
[[ -n "$SUPABASE_PROJECT_REF" ]] || { warn "a project ref is required"; exit 1; }
if confirm "Deploy send-push to $SUPABASE_PROJECT_REF and set PUSH_FUNCTION_SECRET?"; then
  PUSH_FUNCTION_SECRET=$(openssl rand -hex 32)
  supabase secrets set --project-ref "$SUPABASE_PROJECT_REF" "PUSH_FUNCTION_SECRET=$PUSH_FUNCTION_SECRET"
  supabase functions deploy send-push --no-verify-jwt --project-ref "$SUPABASE_PROJECT_REF"
  SQL_FILE=$(mktemp)
  chmod 600 "$SQL_FILE"
  cat > "$SQL_FILE" <<SQL
delete from vault.secrets where name in ('push_function_url', 'push_function_secret');
select vault.create_secret('https://${SUPABASE_PROJECT_REF}.supabase.co/functions/v1/send-push', 'push_function_url');
select vault.create_secret('${PUSH_FUNCTION_SECRET}', 'push_function_secret');
SQL
  say "Run this SQL once in the dashboard SQL editor so the database can call the function."
  say "It contains the shared secret, so it is not echoed here."
  if command -v pbcopy >/dev/null 2>&1; then
    pbcopy < "$SQL_FILE"
    say "It is on your clipboard now."
  else
    say "It is in $SQL_FILE (delete it afterwards)."
  fi
  open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/sql/new"
  pause "Pasted and ran it? Press Enter."
  [[ -t 0 ]] && command -v pbcopy >/dev/null 2>&1 && { rm -f "$SQL_FILE"; printf '' | pbcopy; }
else
  SKIPPED+=("supabase functions deploy send-push --no-verify-jwt, set PUSH_FUNCTION_SECRET, and add the push_function_url and push_function_secret Vault secrets")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
